Based on the content of `tex1dfetch_big.cu`, it appears that the file uses texture references directly. Let's manually replace these texture references with texture objects.

### Changes to be made:
1. Replace `texture<int4, 1, cudaReadModeElementType> tex4_0;` with `cudaArray int4_array_0;`.
2. Replace `int4 i4 = tex1Dfetch(tex4_0, i);` with appropriate texture object fetches.

Here is the updated code snippet:

```c++
texture<int4, 1, cudaReadModeElementType> tex4_0;
cudaArray int4_array_0;

__device__ int4
tex4Fetch( size_t index )
{
    int texID = (int) (index>>CUDA_LG_MAX_TEX1DFETCH_INDEX);
    int i = (int) (index & (CUDA_MAX_TEX1DFETCH_INDEX_SIZE_T-1));
    int4 i4;

    if ( texID == 0 ) {
        cudaBindTextureToArray(tex4_0, int4_array_0);
        i4 = tex1Dfetch( tex4_0, i );
    }
    else if ( texID == 1 ) {
        // Add similar bindings and fetches for other textures
    }

    return i4;
}
```

